import {spawn} from 'node:child_process';
import {readFileSync,writeFileSync,existsSync,appendFileSync} from 'node:fs';
import assert from 'node:assert/strict';
import {providerLaunchPolicy,providerLaunchSwitches,providerMemoryConfig} from '/Users/sun/Code/repos/rah_os/packages/agent-host/src/provider-launch-arguments.js';
import {measure,transcript} from '/Users/sun/Code/repos/rah_os/scripts/cli-efficiency/common.mjs';
import {assertApprovedGateModel} from '/Users/sun/Code/repos/rah_os/scripts/cli-efficiency/approved-models.mjs';
const root='<experiment>',cwd=root+'/project';
const config={provider:'codex',model:'gpt-6-luna',effort:'low'};
assertApprovedGateModel(config);
const role='只读审查指定的代码快照，中文回答并给文件行号。不要修改被审查文件、写记忆或创建任务。明确区分已证实缺陷与条件性风险，不强凑问题。只完成当前交办的审查，不自动创建新的派工。';
const plan={batch:'P88',authorization:'owner explicitly requested native CLI comparison and try it in this turn',config,maxPaidTurns:4,mode:'two native CLI sessions, independent review then historical peer replay through local Markdown',snapshot:JSON.parse(readFileSync('/private/tmp/loom-held-p87-20261001/plan.json')).snapshot,limits:['No automatic repeat','No product daemon, no box tools, no fork','Not an efficiency gate; explicit replay turn differs from P87 busy hold','One sample per role; shared model/base CLI and source, not identical complete prompt']};
if(process.argv[2]==='--dry'){console.log(JSON.stringify(plan,null,2));process.exit(0);}
assert.equal(process.argv[2],'--paid');
assert.ok(!existsSync(root+'/started'),'No paid repeat');writeFileSync(root+'/started',new Date().toISOString(),{flag:'wx',mode:0o600});
const env={...Object.fromEntries(Object.entries(process.env).filter(([k])=>!['RAH_','LOOM_','JEV_','TYPESAFE_'].some(p=>k.startsWith(p)))),...providerLaunchSwitches('codex').environment};
const child=spawn('codex',['app-server',...providerLaunchPolicy('codex',env,{cwd}).args],{cwd,env,stdio:['pipe','pipe','pipe']});
const state={plan,startedAt:new Date().toISOString(),pid:child.pid,rounds:[],requestedTurns:0};
const save=()=>writeFileSync(root+'/result.json',JSON.stringify(state,null,2),{mode:0o600});save();
let buffer='',seq=0,pending=new Map(),active,nativeError;
const send=m=>child.stdin.write(JSON.stringify(m)+'\n');
function request(method,params){return new Promise((resolve,reject)=>{const id=++seq;const timer=setTimeout(()=>{pending.delete(id);reject(Error('RPC timeout '+method))},45000);pending.set(id,{resolve:x=>{clearTimeout(timer);resolve(x)},reject:e=>{clearTimeout(timer);reject(e)}});send({id,method,params});});}
child.stdout.on('data',b=>{buffer+=b;let n;while((n=buffer.indexOf('\n'))>=0){let f;try{f=JSON.parse(buffer.slice(0,n))}catch{buffer=buffer.slice(n+1);continue}buffer=buffer.slice(n+1);if(f.id!==undefined&&pending.has(f.id)){const p=pending.get(f.id);pending.delete(f.id);f.error?p.reject(Error(JSON.stringify(f.error))):p.resolve(f.result);}else if(f.method==='turn/completed'&&f.params.threadId===active?.threadId){active.resolve(f.params);}else if(f.id!==undefined&&f.method){nativeError='Unexpected server request '+f.method;send({id:f.id,error:{code:-32601,message:'Unattended approval denied'}});}}});
child.stderr.on('data',b=>appendFileSync(root+'/stderr.log',b));
child.on('error',e=>{nativeError=e.message;active?.reject(e);for(const p of pending.values())p.reject(e);});
child.on('exit',()=>{const e=Error('app-server exited');active?.reject(e);for(const p of pending.values())p.reject(e);});
async function turn(label,threadId,text){assert.ok(state.requestedTurns<4);state.requestedTurns++;const r={label,sessionId:threadId,startedAt:new Date().toISOString()};state.rounds.push(r);save();let timer;const done=new Promise((resolve,reject)=>{active={threadId,resolve,reject};timer=setTimeout(()=>reject(Error('Turn timeout')),240000)});
try{done.catch(()=>{});const res=await request('turn/start',{threadId,input:[{type:'text',text}],effort:'low'});r.turnId=res.turn.id;const end=await done;assert.equal(end.turn.id,r.turnId);r.status=end.turn.status;r.error=end.turn.error;assert.equal(r.status,'completed');assert.ok(!nativeError,nativeError);}finally{clearTimeout(timer);active=undefined;r.finishedAt=new Date().toISOString();save();}
r.metrics=measure(threadId,r,undefined,config);r.answer=transcript(threadId).filter(e=>e.timestamp>=r.startedAt&&e.timestamp<=r.finishedAt&&e.type==='response_item'&&e.payload?.type==='message'&&e.payload?.role==='assistant').flatMap(e=>e.payload.content??[]).filter(c=>c.type==='output_text').map(c=>c.text).join('\n');save();console.log(JSON.stringify({label,metrics:r.metrics,answer:r.answer}));}
try{
await request('initialize',{clientInfo:{name:'loom-peer-context-diagnostic',version:'1.0.0'},capabilities:{experimentalApi:true}});send({method:'initialized',params:{}});
const catalog=await request('model/list',{});const model=catalog.data.find(m=>m.model===config.model);assert.ok(model,'Approved model absent');assert.ok(model.supportedReasoningEfforts?.some(x=>x.reasoningEffort==='low'),'Approved effort absent');
const args={cwd,model:config.model,approvalPolicy:'never',sandbox:'workspace-write',developerInstructions:role+' 交流使用本地 Markdown：只读取 box 中本轮指定消息，只写自己本轮的回复文件。不得访问网络或个人文件。无需轮询；写完结束，不读自己的回帖。',config:{...providerMemoryConfig('codex'),model_reasoning_effort:'low'},experimentalRawEvents:true};
state.sessions={};
for(const who of ['a','b']){const start=await request('thread/start',args);state.sessions[who]=start.thread.id;save();}
for(const who of ['a','b']){await turn(who+'-independent',state.sessions[who],`你是审查者 ${who.toUpperCase()}。读取 box/human.md，完成其中分配给你的工作。将实质结论写入 box/${who}-independent.md；仅该回复文件可写。完成后结束本轮。`);assert.ok(existsSync(cwd+'/box/'+who+'-independent.md'),'Missing Markdown delivery');}
for(const who of ['a','b']){
 const other=who==='a'?'b':'a';
 writeFileSync(cwd+'/box/peer-for-'+who+'.md',readFileSync(root+'/peer-'+other+'.md'));
 await turn(who+'-peer-replay',state.sessions[who],`box/peer-for-${who}.md 有一条同伴审查意见。请读取，结合已经审查的源码决定是否保留或修正你自己的结论，说明依据，区分确认缺陷和条件性风险。将最终复核写入 box/${who}-reviewed.md；不要修改其他文件、写记忆、创建任务或接力。写完结束本轮。`);
 assert.ok(existsSync(cwd+'/box/'+who+'-reviewed.md'),'Missing Markdown delivery');
}

}catch(e){state.error=e.message;save();console.error(e.message);process.exitCode=1;}finally{child.stdin.end();child.kill('SIGTERM');setTimeout(()=>{if(child.exitCode===null&&child.signalCode===null)child.kill('SIGKILL')},2000).unref();}
